import datetime
import math
import re
import polars as pl

NULL_VALUES = {"", "N/A", "n/a", "-", "null", "NULL"}


def _clean_str(col: pl.Expr) -> pl.Expr:
    return pl.when(col.is_in(list(NULL_VALUES))).then(None).otherwise(col)


def transform(raw: pl.DataFrame) -> pl.DataFrame:
    return raw.select(
        device_id=_clean_str(pl.col("dev")).str.to_uppercase(),
        read_at=_clean_str(pl.col("ts")).str.to_datetime(
            format="%Y-%m-%dT%H:%M:%SZ", strict=False, time_unit="us"
        ),
        temperature_c=_clean_str(pl.col("payload.t"))
        .cast(pl.Float64, strict=False)
        .round(2),
        humidity_pct=_clean_str(pl.col("payload.h"))
        .cast(pl.Float64, strict=False)
        .round(2),
        battery_v=(
            _clean_str(pl.col("payload.bat_mv")).cast(pl.Float64, strict=False)
            * 0.001
        ).round(2),
    )
